using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// Script de debug para verificar y forzar el guardado de progreso de niveles.
/// Agregar este componente temporalmente a un GameObject en la escena para hacer pruebas.
/// </summary>
public class LevelProgressDebugger : MonoBehaviour
{
    [Header("Testing")]
    [SerializeField] private string testLevelName = "Level1";

    [Header("Auto Test en Victoria")]
    [SerializeField] private bool autoTestOnVictory = true;

    private void Start()
    {
        Debug.Log("=== LEVEL PROGRESS DEBUGGER INICIADO ===");

        // Verificar que exista el LevelProgressManager
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogWarning("⚠️ NO SE ENCONTRÓ LevelProgressManager.Instance");

            LevelProgressManager manager = FindFirstObjectByType<LevelProgressManager>();
            if (manager == null)
            {
                Debug.LogError("❌ NO HAY LevelProgressManager EN LA ESCENA");
            }
            else
            {
                Debug.Log("✅ LevelProgressManager encontrado pero no es Instance");
            }
        }
        else
        {
            Debug.Log("✅ LevelProgressManager.Instance existe correctamente");
        }

        // Verificar GameConditionManager
        if (GameConditionManager.Instance == null)
        {
            Debug.LogWarning("⚠️ NO SE ENCONTRÓ GameConditionManager.Instance");
        }
        else
        {
            Debug.Log("✅ GameConditionManager.Instance existe");

            // Suscribirse al evento de victoria para hacer debug
            if (autoTestOnVictory)
            {
                GameConditionManager.Instance.OnVictoria.AddListener(OnVictoriaDetectada);
                Debug.Log(" Suscrito al evento OnVictoria para debug");
            }
        }

        // Mostrar nombre de la escena actual
        string currentScene = SceneManager.GetActiveScene().name;
        Debug.Log($" Escena actual: '{currentScene}'");
    }

    private void OnVictoriaDetectada()
    {
        Debug.Log("===  VICTORIA DETECTADA - INICIANDO DEBUG ===");

        string currentScene = SceneManager.GetActiveScene().name;
        Debug.Log($" Nivel completado: '{currentScene}'");

        // Esperar un frame para que se guarde
        StartCoroutine(VerificarGuardadoDespuesDeVictoria(currentScene));
    }

    private System.Collections.IEnumerator VerificarGuardadoDespuesDeVictoria(string levelName)
    {
        yield return new WaitForSeconds(0.5f);

        Debug.Log("=== VERIFICANDO GUARDADO ===");

        if (LevelProgressManager.Instance != null)
        {
            bool isCompleted = LevelProgressManager.Instance.IsLevelCompleted(levelName);
            Debug.Log($" Nivel '{levelName}' completado en PlayerPrefs: {isCompleted}");

            if (isCompleted)
            {
                Debug.Log("✅ ¡EL PROGRESO SE GUARDÓ CORRECTAMENTE!");
            }
            else
            {
                Debug.LogError("❌ EL PROGRESO NO SE GUARDÓ - Verificar condiciones");

                // Verificar vidas
                var lifeStarsUI = FindFirstObjectByType<LifeStarsUI>();
                if (lifeStarsUI != null)
                {
                    int lives = lifeStarsUI.GetCurrentLives();
                    Debug.Log($"⭐ Vidas restantes: {lives}");

                    if (lives <= 0)
                    {
                        Debug.LogWarning("⚠️ El jugador no tiene vidas, por eso no se guardó");
                    }
                }
            }
        }
        else
        {
            Debug.LogError("❌ LevelProgressManager.Instance es NULL después de victoria");
        }

        Debug.Log("=== FIN VERIFICACIÓN ===");
    }

    #region Botones de Debug (Context Menu)

    [ContextMenu("1. Mostrar Estado Actual")]
    public void MostrarEstadoActual()
    {
        Debug.Log("=== ESTADO ACTUAL DEL SISTEMA ===");

        string currentScene = SceneManager.GetActiveScene().name;
        Debug.Log($" Escena actual: '{currentScene}'");

        // Verificar LevelProgressManager
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ LevelProgressManager.Instance NO EXISTE");
        }
        else
        {
            Debug.Log("✅ LevelProgressManager.Instance EXISTE");
            bool isCompleted = LevelProgressManager.Instance.IsLevelCompleted(currentScene);
            Debug.Log($" Nivel '{currentScene}' completado: {isCompleted}");
        }

        // Verificar GameConditionManager
        if (GameConditionManager.Instance == null)
        {
            Debug.LogError("❌ GameConditionManager.Instance NO EXISTE");
        }
        else
        {
            Debug.Log("✅ GameConditionManager.Instance EXISTE");
        }

        // Verificar LifeStarsUI
        var lifeStarsUI = FindFirstObjectByType<LifeStarsUI>();
        if (lifeStarsUI != null)
        {
            int lives = lifeStarsUI.GetCurrentLives();
            Debug.Log($"⭐ Vidas actuales: {lives}");
        }
        else
        {
            Debug.LogWarning("⚠️ No se encontró LifeStarsUI");
        }

        Debug.Log("=== FIN ESTADO ===");
    }

    [ContextMenu("2. Forzar Guardar Nivel Actual")]
    public void ForzarGuardarNivelActual()
    {
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ No se puede guardar: LevelProgressManager.Instance no existe");
            return;
        }

        string currentScene = SceneManager.GetActiveScene().name;
        Debug.Log($" Forzando guardado del nivel '{currentScene}'...");

        LevelProgressManager.Instance.MarkLevelAsCompleted(currentScene);

        // Verificar que se guardó
        bool isCompleted = LevelProgressManager.Instance.IsLevelCompleted(currentScene);
        if (isCompleted)
        {
            Debug.Log($"✅ Nivel '{currentScene}' marcado como completado EXITOSAMENTE");
        }
        else
        {
            Debug.LogError($"❌ ERROR: No se pudo marcar el nivel como completado");
        }
    }

    [ContextMenu("3. Verificar PlayerPrefs Directamente")]
    public void VerificarPlayerPrefs()
    {
        string currentScene = SceneManager.GetActiveScene().name;
        string key = $"Level_{currentScene}_Completed";

        Debug.Log($"=== VERIFICACIÓN DIRECTA DE PLAYERPREFS ===");
        Debug.Log($" Key: '{key}'");

        int value = PlayerPrefs.GetInt(key, -1);

        if (value == -1)
        {
            Debug.Log("❌ La key NO EXISTE en PlayerPrefs");
        }
        else if (value == 0)
        {
            Debug.Log("⚠️ La key existe pero el valor es 0 (no completado)");
        }
        else if (value == 1)
        {
            Debug.Log("✅ La key existe y el valor es 1 (COMPLETADO)");
        }
        else
        {
            Debug.Log($"⚠️ La key existe pero tiene un valor inesperado: {value}");
        }

        Debug.Log("=== FIN VERIFICACIÓN PLAYERPREFS ===");
    }

    [ContextMenu("4. Guardar Nivel de Prueba")]
    public void GuardarNivelDePrueba()
    {
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ No se puede guardar: LevelProgressManager.Instance no existe");
            return;
        }

        Debug.Log($" Guardando nivel de prueba '{testLevelName}'...");
        LevelProgressManager.Instance.MarkLevelAsCompleted(testLevelName);

        bool isCompleted = LevelProgressManager.Instance.IsLevelCompleted(testLevelName);
        if (isCompleted)
        {
            Debug.Log($"✅ Nivel de prueba '{testLevelName}' guardado EXITOSAMENTE");
        }
    }

    [ContextMenu("5. Limpiar Progreso Nivel Actual")]
    public void LimpiarProgresoNivelActual()
    {
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ No se puede limpiar: LevelProgressManager.Instance no existe");
            return;
        }

        string currentScene = SceneManager.GetActiveScene().name;
        Debug.Log($"️ Limpiando progreso del nivel '{currentScene}'...");

        LevelProgressManager.Instance.ClearLevelProgress(currentScene);
        Debug.Log($"✅ Progreso limpiado");
    }

    [ContextMenu("6. Mostrar TODOS los Niveles Completados")]
    public void MostrarTodosLosNivelesCompletados()
    {
        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ LevelProgressManager.Instance no existe");
            return;
        }

        LevelProgressManager.Instance.ShowLevelProgress();
    }

    [ContextMenu("7. Test Completo de Guardado")]
    public void TestCompletoDeGuardado()
    {
        Debug.Log("=== TEST COMPLETO DE GUARDADO ===");

        string testLevel = "TestLevel123";

        if (LevelProgressManager.Instance == null)
        {
            Debug.LogError("❌ FALLO: LevelProgressManager.Instance no existe");
            return;
        }

        Debug.Log($"1. Verificando que '{testLevel}' NO está completado...");
        bool antes = LevelProgressManager.Instance.IsLevelCompleted(testLevel);
        Debug.Log($"   Estado inicial: {antes}");

        Debug.Log($"2. Marcando '{testLevel}' como completado...");
        LevelProgressManager.Instance.MarkLevelAsCompleted(testLevel);

        Debug.Log($"3. Verificando que '{testLevel}' SÍ está completado...");
        bool despues = LevelProgressManager.Instance.IsLevelCompleted(testLevel);
        Debug.Log($"   Estado después: {despues}");

        if (despues)
        {
            Debug.Log("✅ TEST EXITOSO: El sistema de guardado funciona correctamente");
        }
        else
        {
            Debug.LogError("❌ TEST FALLIDO: El nivel no se marcó como completado");
        }

        Debug.Log($"4. Limpiando nivel de prueba...");
        LevelProgressManager.Instance.ClearLevelProgress(testLevel);

        Debug.Log("=== FIN TEST ===");
    }

    #endregion

    private void OnDestroy()
    {
        // Desuscribirse del evento
        if (GameConditionManager.Instance != null)
        {
            GameConditionManager.Instance.OnVictoria.RemoveListener(OnVictoriaDetectada);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;

/// <summary>
/// Script que se coloca en cada Canvas de niveles (PrehistoricLevels, MedievalLevels, etc).
/// Contiene las referencias a los botones de nivel y sus estrellas.
/// Se registra con LevelProgressManager en Start.
/// </summary>
public class MenuLevelUpdater : MonoBehaviour
{
    [System.Serializable]
    public class LevelButton
    {
        public string levelSceneName; // Nombre de la escena (ej: "Level1", "Level0_M")
        public Button button; // Referencia al botón
        public Image completionStar; // Imagen de estrella
    }

    [Header("Referencias de Botones")]
    [SerializeField] private List<LevelButton> levelButtons = new List<LevelButton>();

    [Header("Debug")]
    [SerializeField] private bool showDebugLogs = true;

    private void Start()
    {
        if (showDebugLogs)
        {
            Debug.Log($" MenuLevelUpdater en '{gameObject.name}' iniciado - Registrándose con LevelProgressManager...");
        }

        // Buscar el LevelProgressManager y registrarse
        LevelProgressManager manager = FindFirstObjectByType<LevelProgressManager>();

        if (manager != null)
        {
            // Llamar al método público del manager para que nos busque y actualice
            manager.RegisterAndUpdateLevelUpdater();
        }
        else
        {
            Debug.LogWarning("⚠️ No se encontró LevelProgressManager en la escena");
        }
    }

    /// <summary>
    /// Actualiza las estrellas según el progreso.
    /// Es llamado por LevelProgressManager.
    /// </summary>
    public void UpdateStars(LevelProgressManager manager)
    {
        if (manager == null)
        {
            if (showDebugLogs)
            {
                Debug.LogWarning("⚠️ LevelProgressManager es null");
            }
            return;
        }

        if (showDebugLogs)
        {
            Debug.Log($" Actualizando {levelButtons.Count} estrellas...");
        }

        int updated = 0;
        int completed = 0;
        int skipped = 0;

        foreach (var levelButton in levelButtons)
        {
            // Verificar referencias
            if (levelButton.button == null || levelButton.completionStar == null)
            {
                skipped++;
                continue;
            }

            // Preguntar al manager si el nivel está completado
            bool isCompleted = manager.IsLevelCompleted(levelButton.levelSceneName);

            // Activar/desactivar la estrella
            levelButton.completionStar.gameObject.SetActive(isCompleted);

            updated++;
            if (isCompleted)
            {
                completed++;

                if (showDebugLogs)
                {
                    Debug.Log($"⭐ Nivel '{levelButton.levelSceneName}' - COMPLETADO");
                }
            }
        }

        if (showDebugLogs)
        {
            Debug.Log($"✅ {updated} estrellas actualizadas, {completed} niveles completados, {skipped} saltados");
        }
    }

    /// <summary>
    /// Obtiene la lista de botones.
    /// </summary>
    public List<LevelButton> GetLevelButtons()
    {
        return levelButtons;
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;

/// <summary>
/// Script que se coloca en cada Canvas de niveles (PrehistoricLevels, MedievalLevels, etc).
/// Contiene las referencias a los botones de nivel y sus estrellas.
/// Se registra con LevelProgressManager en Start.
/// </summary>
public class MenuLevelUpdater : MonoBehaviour
{
    [System.Serializable]
    public class LevelButton
    {
        public string levelSceneName; // Nombre de la escena (ej: "Level1", "Level0_M")
        public Button button; // Referencia al botón
        public Image completionStar; // Imagen de estrella
    }

    [System.Serializable]
    public class EraButton
    {
        public string eraName; // Nombre de la era (ej: "Prehistoric", "Medieval")
        public Button button; // Referencia al botón de la era
        public Image completionStar; // Imagen de estrella de la era
        public List<int> levelButtonIndices; // Índices de los LevelButton en la lista levelButtons
    }

    [Header("Referencias de Botones")]
    [SerializeField] private List<LevelButton> levelButtons = new List<LevelButton>();

    [Header("Referencias de Eras")]
    [SerializeField] private List<EraButton> eraButtons = new List<EraButton>();

    [Header("Debug")]
    [SerializeField] private bool showDebugLogs = true;

    private void Start()
    {
        if (showDebugLogs)
        {
            Debug.Log($" MenuLevelUpdater en '{gameObject.name}' iniciado - Registrándose con LevelProgressManager...");
        }

        // Buscar el LevelProgressManager y registrarse
        LevelProgressManager manager = FindFirstObjectByType<LevelProgressManager>();

        if (manager != null)
        {
            // Llamar al método público del manager para que nos busque y actualice
            manager.RegisterAndUpdateLevelUpdater();
        }
        else
        {
            Debug.LogWarning("⚠️ No se encontró LevelProgressManager en la escena");
        }
    }

    /// <summary>
    /// Actualiza las estrellas según el progreso.
    /// Es llamado por LevelProgressManager.
    /// </summary>
    public void UpdateStars(LevelProgressManager manager)
    {
        if (manager == null)
        {
            if (showDebugLogs)
            {
                Debug.LogWarning("⚠️ LevelProgressManager es null");
            }
            return;
        }

        if (showDebugLogs)
        {
            Debug.Log($" Actualizando {levelButtons.Count} estrellas...");
        }

        int updated = 0;
        int completed = 0;
        int skipped = 0;

        foreach (var levelButton in levelButtons)
        {
            // Verificar referencias
            if (levelButton.button == null || levelButton.completionStar == null)
            {
                skipped++;
                continue;
            }

            // Preguntar al manager si el nivel está completado
            bool isCompleted = manager.IsLevelCompleted(levelButton.levelSceneName);

            // Activar/desactivar la estrella
            levelButton.completionStar.gameObject.SetActive(isCompleted);

            updated++;
            if (isCompleted)
            {
                completed++;

                if (showDebugLogs)
                {
                    Debug.Log($"⭐ Nivel '{levelButton.levelSceneName}' - COMPLETADO");
                }
            }
        }

        if (showDebugLogs)
        {
            Debug.Log($"✅ {updated} estrellas actualizadas, {completed} niveles completados, {skipped} saltados");
        }

        // Actualizar estrellas de eras
        UpdateEraStars(manager);
    }

    /// <summary>
    /// Actualiza las estrellas de las eras.
    /// Una era se marca como completada si TODOS sus niveles están completados.
    /// </summary>
    private void UpdateEraStars(LevelProgressManager manager)
    {
        if (manager == null)
        {
            return;
        }

        if (eraButtons.Count == 0)
        {
            return; // No hay eras configuradas
        }

        if (showDebugLogs)
        {
            Debug.Log($" Actualizando {eraButtons.Count} estrellas de eras...");
        }

        int eraUpdated = 0;
        int eraCompleted = 0;
        int eraSkipped = 0;

        foreach (var eraButton in eraButtons)
        {
            // Verificar referencias
            if (eraButton.button == null || eraButton.completionStar == null)
            {
                eraSkipped++;
                continue;
            }

            // Verificar si la era tiene niveles
            if (eraButton.levelButtonIndices == null || eraButton.levelButtonIndices.Count == 0)
            {
                if (showDebugLogs)
                {
                    Debug.LogWarning($"⚠️ Era '{eraButton.eraName}' no tiene niveles configurados");
                }
                eraSkipped++;
                continue;
            }

            // Verificar si TODOS los niveles de la era están completados
            bool allLevelsCompleted = true;
            int completedLevels = 0;
            int totalLevels = 0;

            foreach (int levelIndex in eraButton.levelButtonIndices)
            {
                // Verificar que el índice sea válido
                if (levelIndex < 0 || levelIndex >= levelButtons.Count)
                {
                    if (showDebugLogs)
                    {
                        Debug.LogWarning($"⚠️ Índice {levelIndex} fuera de rango en era '{eraButton.eraName}'");
                    }
                    continue;
                }

                // Obtener el LevelButton desde la lista usando el índice
                LevelButton levelButton = levelButtons[levelIndex];

                if (string.IsNullOrEmpty(levelButton.levelSceneName))
                {
                    continue; // Saltar niveles sin nombre configurado
                }

                totalLevels++;

                // Preguntar al manager si el nivel está completado
                bool isLevelCompleted = manager.IsLevelCompleted(levelButton.levelSceneName);

                if (isLevelCompleted)
                {
                    completedLevels++;
                }
                else
                {
                    allLevelsCompleted = false;
                }
            }

            // Activar/desactivar la estrella de la era
            eraButton.completionStar.gameObject.SetActive(allLevelsCompleted && totalLevels > 0);

            eraUpdated++;
            if (allLevelsCompleted && totalLevels > 0)
            {
                eraCompleted++;

                if (showDebugLogs)
                {
                    Debug.Log($"⭐ Era '{eraButton.eraName}' - COMPLETADA ({completedLevels}/{totalLevels} niveles)");
                }
            }
            else
            {
                if (showDebugLogs)
                {
                    Debug.Log($" Era '{eraButton.eraName}' - {completedLevels}/{totalLevels} niveles completados");
                }
            }
        }

        if (showDebugLogs)
        {
            Debug.Log($"✅ Eras: {eraUpdated} actualizadas, {eraCompleted} completadas, {eraSkipped} saltadas");
        }
    }

    /// <summary>
    /// Obtiene la lista de botones.
    /// </summary>
    public List<LevelButton> GetLevelButtons()
    {
        return levelButtons;
    }

    /// <summary>
    /// Obtiene la lista de botones de eras.
    /// </summary>
    public List<EraButton> GetEraButtons()
    {
        return eraButtons;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Objeto genérico tipo 3 que permite al jugador obtener un material tipo 3 (superficie)
/// al mantener presionado el botón de interacción durante 1 segundo.
/// En la era prehistórica, este material es un adoquín.
/// </summary>
public class GenericObject3 : MonoBehaviour, IInteractable, IHoldInteractable
{    
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; // Referencia al SO con los prefabs
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;
    [SerializeField] private GameObject shadow;

    [Header("Configuración de generación")]
    [SerializeField] private float tiempoPresionado = 1.0f; // Tiempo que hay que mantener presionado
    [SerializeField] private float tiempoRecarga = 2.0f; // Tiempo antes de poder generar otro material

    // Variables para controlar el estado
    private bool enRecarga = false;
    private bool enProceso = false;
    private float tiempoActual = 0f;
    private GameObject jugadorInteractuando = null;

    // Propiedad requerida por la interfaz IInteractable
    public InteractPriority InteractPriority => interactPriority;    

    private void Start()
    {
        // Verificar que tengamos las referencias necesarias
        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }

        shadow.SetActive(false);
    }

    private void Update()
    {
        // Si estamos en proceso de generar el material
        if (enProceso && jugadorInteractuando != null)
        {
            tiempoActual += Time.deltaTime;

            // Si se completa el tiempo requerido
            if (tiempoActual >= tiempoPresionado)
            {
                EntregarMaterial();
                ResetearProceso();
                StartCoroutine(Recargar());
            }

            // Aquí podrías añadir efectos visuales o sonidos que indiquen el progreso
            // Por ejemplo, una barra de progreso o un efecto de partículas que aumenta
        }
    }

    // Método llamado cuando un jugador interactúa con este objeto
    public void Interact(GameObject interactor)
    {
        if (enRecarga)
        {
            Debug.Log("Objeto en recarga, espera un momento.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            // Iniciamos el proceso de mantener presionado
            if (!enProceso)
            {
                IniciarProceso(interactor);
                Debug.Log("Mantén presionado para obtener el material tipo 3 (superficie).");
            }
        }
        else
        {
            Debug.Log("El interactor no tiene el componente PlayerObjectHolder.");
        }
    }

    // Método llamado cuando el jugador suelta el botón de interacción
    public void DetenerInteraccion()
    {
        if (enProceso)
        {
            ResetearProceso();
            Debug.Log("Proceso cancelado. Debes mantener presionado el botón.");
        }
    }

    private void IniciarProceso(GameObject interactor)
    {
        enProceso = true;
        tiempoActual = 0f;
        jugadorInteractuando = interactor;

        // Aquí podrías iniciar efectos visuales o sonidos
    }

    private void ResetearProceso()
    {
        enProceso = false;
        tiempoActual = 0f;
        jugadorInteractuando = null;

        // Detener efectos visuales o sonidos
    }    

    private void EntregarMaterial()
    {
        if (materialPrefabsSO == null || jugadorInteractuando == null)
        {
            Debug.LogError("Falta MaterialPrefabSO o jugador para entregar material.");
            return;
        }

        // Obtener el prefab del material tipo 3 para la era actual
        GameObject materialPrefab = materialPrefabsSO.GetMaterialPrefab(3, era);

        if (materialPrefab == null)
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = jugadorInteractuando.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            if (playerObjectHolder.HasObjectInHand())
            {
                Debug.Log("Jugador ya sostiene un objeto. Intercambiando objetos.");
            }

            // Generar una nueva instancia del material de superficie en la escena
            GameObject nuevoMaterial = Instantiate(materialPrefab, transform.position + Vector3.up * 0.5f, transform.rotation);

            // Configurar el material generado
            ConfigurarMaterialGenerado(nuevoMaterial);

            // Lógica para asignar el UIIndex al nuevo material, igual que GenericObject1
            UIIndexSetter sourceIndexSetter = GetComponent<UIIndexSetter>();
            int indexToAssign = sourceIndexSetter != null ? sourceIndexSetter.UIIndex : -1;

            UIIndexSetter uiIndexSetter = nuevoMaterial.GetComponent<UIIndexSetter>();
            if (uiIndexSetter == null)
            {
                uiIndexSetter = nuevoMaterial.AddComponent<UIIndexSetter>();
            }
            uiIndexSetter.SetUIIndex(indexToAssign);

            // Hacer que el jugador recoja la instancia recién creada
            playerObjectHolder.PickUpExistingInstance(nuevoMaterial);
            Debug.Log("Material tipo 3 (superficie) entregado con éxito.");

            // Opcional: Reproducir sonido o efecto visual
            ProducirEfectos();
        }
    }

    private void ConfigurarMaterialGenerado(GameObject material)
    {
        // Configurar el material generado como material de tipo superficie (nuevo tipo 3) de la era correspondiente
        BridgeMaterialInfo materialInfo = material.GetComponent<BridgeMaterialInfo>();
        if (materialInfo == null)
        {
            materialInfo = material.AddComponent<BridgeMaterialInfo>();
        }

        materialInfo.layerIndex = 2; // Tipo superficie corresponde a la capa superior (índice 2)
        materialInfo.era = era;
        materialInfo.materialType = BridgeQuadrantSO.MaterialType.Stone; // Superficie usa piedra/adoquín

        material.tag = "BridgeLayer2";

        Debug.Log($"Material superficie generado configurado: Era {era}, Capa 2, Tipo Stone");
    }

    private IEnumerator Recargar()
    {
        enRecarga = true;

        // TODO: Aquí puedes añadir una animación o cambio visual que indique la recarga

        yield return new WaitForSeconds(tiempoRecarga);

        enRecarga = false;
    }

    private void ProducirEfectos()
    {
        // TODO: Reproducir efectos visuales o sonidos
    }
}

